WITH with_gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) > INTERVAL 90 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM sessions), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT country, SUM(CASE WHEN country = 'TH' THEN island_id ELSE 0 END) AS th_island_id, COUNT(*) FILTER (WHERE device = 'desktop') AS desktop_rows, COUNT_IF(country = 'DE') AS de_events, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS span_minutes FROM sessionized GROUP BY country ORDER BY span_minutes DESC
